local LOGO_IMAGE = "rbxassetid://84034353458936"
local LOGO_B64 = ""
pcall(function()
    if type(writefile) ~= "function" then return end
    local getAsset = getcustomasset or getsynasset
    if type(getAsset) ~= "function" then return end
    local raw
    if crypt and crypt.base64decode then raw = crypt.base64decode(LOGO_B64)
    elseif base64 and base64.decode then raw = base64.decode(LOGO_B64)
    elseif type(base64_decode) == "function" then raw = base64_decode(LOGO_B64)
    end
    if not raw then return end
    writefile("BintangHubLogo.png", raw)
    local asset = getAsset("BintangHubLogo.png")
    if asset and asset ~= "" then
        LOGO_IMAGE = asset
        -- Astra Logo may need number; keep numeric fallback for CreateWindow
    end
end)


