    function ClearHookESP()
        -- Hapus semua label custom yang pernah dibuat oleh logic ini.
        pcall(function()
            local pg = LocalPlayer:FindFirstChild("PlayerGui")
            if not pg then return end
            for _, gui in ipairs(pg:GetChildren()) do
                if gui:IsA("ScreenGui") and gui.Name:match("%-mob$") then
                    local frame = gui:FindFirstChild("Frame")
                    if frame then
                        for i = 1, 5 do
                            local sf = frame:FindFirstChild("Survivor" .. i)
                            local il = sf and sf:FindFirstChild("ImageLabel")
                            local lbl = il and il:FindFirstChild("MWD_CustomHookCounter")
                            if lbl then lbl:Destroy() end
                        end
                    end
                end
            end
        end)
    end

    function UpdateHookESP()
        -- Fungsi ini sekarang artinya "enabled". Pas toggle OFF dipanggil ClearHookESP.
        -- Pas ON dipanggil UpdateHookCounter.
        if not HookESPEnabled then ClearHookESP(); return end
        pcall(UpdateHookCounter)
    end

    -- Logic inti dari mawwwhub
    function UpdateHookCounter()
        local pg = LocalPlayer:FindFirstChild("PlayerGui")
        if not pg then return end
        for _, gui in ipairs(pg:GetChildren()) do
            if gui:IsA("ScreenGui") and gui.Name:match("%-mob$") then
                local frame = gui:FindFirstChild("Frame")
                if frame then
                    for i = 1, 5 do
                        local sf = frame:FindFirstChild("Survivor" .. i)
                        local il = sf and sf:FindFirstChild("ImageLabel")
                        local tl = sf and sf:FindFirstChild("TextLabel")
                        if il and tl then
                            local lbl = il:FindFirstChild("MWD_CustomHookCounter")
                            local pName = tl.Text
                            local target
                            for _, p in ipairs(_GetPlayers()) do
                                if p.Name == pName or p.DisplayName == pName then
                                    target = p; break
                                end
                            end
                            local cnt = 0
                            if target then
                                cnt = target:GetAttribute("HookCount")
                                    or (target.Character and target.Character:GetAttribute("HookCount"))
                                    or 0
                            end
                            if not lbl then
                                lbl = Instance.new("TextLabel", il)
                                lbl.Name = "MWD_CustomHookCounter"
                                lbl.Size = UDim2.new(1, 0, 0.35, 0)
                                lbl.Position = UDim2.new(0, 0, 0.65, 0)
                                lbl.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
                                lbl.BackgroundTransparency = 0.5
                                lbl.TextStrokeTransparency = 0
                                lbl.TextScaled = true
                                lbl.Font = Enum.Font.SourceSansBold
                            end
                            lbl.Visible = true
                            if cnt >= 3 then
                                lbl.Text = "DEAD"
                                lbl.TextColor3 = Color3.fromRGB(255, 75, 75)
                            else
                                lbl.Text = "Hooks: " .. tostring(cnt)
                                if cnt == 2 then
                                    lbl.TextColor3 = Color3.fromRGB(255, 140, 0)
                                elseif cnt == 1 then
                                    lbl.TextColor3 = Color3.fromRGB(255, 215, 0)
                                else
                                    lbl.TextColor3 = Color3.fromRGB(255, 255, 255)
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    -- Watcher: panggil UpdateHookCounter tiap 0.25s kalau toggle ON.
    task.spawn(function()
        while true do
            task.wait(0.25)
            if HookESPEnabled then
                pcall(UpdateHookCounter)
            end
        end
    end)

    -- ============ HIT SOUND (REUSE INSTANCE) ============
    local _hitSoundCache = nil
    function PlayHitSound()
        if not Config.HitSoundEnabled then return end
        local now = tick()
        if now - Config.HitSoundLastTime < Config.HitSoundCooldown then return end
        Config.HitSoundLastTime = now
        pcall(function()
            if not _hitSoundCache or not _hitSoundCache.Parent then
                _hitSoundCache = Instance.new("Sound")
                _hitSoundCache.SoundId = Config.HitSoundId
                _hitSoundCache.Parent = workspace.CurrentCamera or workspace
            end
            _hitSoundCache.Volume = Config.HitSoundVolume
            _hitSoundCache:Play()
        end)
    end

    -- ============ AUTO RUN MOBILE ============
    getgenv().AutoRunMobileEnabled = false
    local AutoRunMobileThread = nil
    local function GetMobileSprintButton()
        local pg = LocalPlayer:FindFirstChild("PlayerGui"); if not pg then return nil end
        local mob = pg:FindFirstChild("Survivor-mob"); if not mob then return nil end
        local controls = mob:FindFirstChild("Controls"); if not controls then return nil end
        local sprint = controls:FindFirstChild("sprint"); if not sprint then return nil end
        if sprint:IsA("GuiButton") then return sprint end
        local icon = sprint:FindFirstChild("icon")
        if icon and icon:IsA("GuiButton") then return icon end
        if icon and icon.Parent and icon.Parent:IsA("GuiButton") then return icon.Parent end
        if sprint.Parent and sprint.Parent:IsA("GuiButton") then return sprint.Parent end
        return sprint
    end
    local function PressSprint()
        local btn = GetMobileSprintButton()
        if not btn then return false end
        pcall(function()
            if type(firesignal) == "function" then
                firesignal(btn.MouseButton1Click); firesignal(btn.MouseButton1Down)
                task.wait(0.04); firesignal(btn.MouseButton1Up)
            else
                local pos = btn.AbsolutePosition; local size = btn.AbsoluteSize
                local inset = GuiService:GetGuiInset()
                local x = pos.X + size.X/2 + inset.X; local y = pos.Y + size.Y/2 + inset.Y
