    local function startSkillCheck()
        if Connections.SkillHeartbeat then Connections.SkillHeartbeat:Disconnect() end
        Connections.SkillHeartbeat = RunService.Heartbeat:Connect(function()
            if not Auto.SkillCheck or State.busy then return end
            local prompt = PlayerGui:FindFirstChild("SkillCheckPromptGui"); if not prompt then return end
            local check = prompt:FindFirstChild("Check")
            if not check or not check.Visible then State.RandomMode_IsNormal = false; return end
            local line = check:FindFirstChild("Line"); local goal = check:FindFirstChild("Goal")
            if not line or not goal then return end
            local isInstant = Auto.SkillCheckMode == "Instant" or (Auto.SkillCheckMode == "Random" and not State.RandomMode_IsNormal)
            if isInstant then
                line.Rotation = goal.Rotation + 109
                State.busy = true
                task.spawn(function() TriggerSkillCheck(); task.wait(0.05); State.busy = false end)
            else
                local isNormal = Auto.SkillCheckMode == "Normal" or (Auto.SkillCheckMode == "Random" and State.RandomMode_IsNormal)
                local lr = line.Rotation % 360; local gr = goal.Rotation % 360
                local sR, eR
                if isNormal then sR = (gr + 116) % 360; eR = (gr + 140) % 360
                else sR = (gr + 102) % 360; eR = (gr + 116) % 360 end
                local inZone = false
                if sR > eR then inZone = (lr >= sR or lr <= eR)
                else inZone = (lr >= sR and lr <= eR) end
                if inZone then
                    State.busy = true
                    task.spawn(function() TriggerSkillCheck(); task.wait(0.05); State.busy = false end)
                end
            end
        end)
    end

    local function getClosestSurvivorForStalk()
        local root = getRoot(); if not root then return nil end
        local closest, shortest = nil, math.huge
        for _, plr in pairs(_GetPlayers()) do
            if plr ~= LocalPlayer and plr.Character then
                local hum = plr.Character:FindFirstChildOfClass("Humanoid")
                local hrp = plr.Character:FindFirstChild("HumanoidRootPart")
                if hum and hrp and hum.Health > 30 then
                    local d = (hrp.Position - root.Position).Magnitude
                    if d <= AutoStalk.StalkRange and d < shortest then
                        shortest = d; closest = plr
                    end
                end
            end
        end
        return closest
    end
    function getTargetPartObject(char)
        if AimConfig.AIM_TargetPart == "Head" then return char:FindFirstChild("Head")
        elseif AimConfig.AIM_TargetPart == "Root" or AimConfig.AIM_TargetPart == "HumanoidRootPart" then
            return char:FindFirstChild("HumanoidRootPart")
        else return char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso") or char:FindFirstChild("HumanoidRootPart") end
    end

    -- ============ OPTIMIZED: getClosestSurvivor WITH CACHE ============
    local _closestSurvivorCache = nil
    local _closestSurvivorCacheTime = 0
    function getClosestSurvivor()
        if tick() - _closestSurvivorCacheTime < 0.15 and _closestSurvivorCache ~= nil then
            if _closestSurvivorCache.Parent then return _closestSurvivorCache end
        end
        local myChar = player.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart"); if not myRoot then return nil end
        local closestFovDist = AimConfig.Veil_FOV
        local closestTarget = nil
        local cam = workspace.CurrentCamera
        local centerScreen = Vector2.new(cam.ViewportSize.X/2, cam.ViewportSize.Y/2)
        for _, p in ipairs(_GetPlayers()) do
            if p ~= player and p.Team and p.Team.Name == "Survivors" and p.Character then
                local char = p.Character
                local hum = char:FindFirstChildOfClass("Humanoid")
                local tp = getTargetPartObject(char)
                if hum and hum.Health > 0 and tp then
                    local d3 = (tp.Position - myRoot.Position).Magnitude
                    if d3 <= AimConfig.SPEAR_MaxDist then
                        local sp, on = cam:WorldToViewportPoint(tp.Position)
                        if on then
                            local d2 = (Vector2.new(sp.X, sp.Y) - centerScreen).Magnitude
                            if d2 <= closestFovDist then closestFovDist = d2; closestTarget = tp end
                        end
                    end
                end
            end
        end
        _closestSurvivorCache = closestTarget
        _closestSurvivorCacheTime = tick()
        return closestTarget
    end
