    local function setupFlowstate(char)
        if FakePerks.fsConnection then FakePerks.fsConnection:Disconnect(); FakePerks.fsConnection = nil end
        if FakePerks.fsAnimConnection then FakePerks.fsAnimConnection:Disconnect(); FakePerks.fsAnimConnection = nil end
