    local ItemsFolder = ReplicatedStorage:WaitForChild("Items", 5)
    function extractAssetId(str) return tostring(str):match("%d+") end
    function getItemIcon(name)
        if not ItemsFolder then return nil end
        local item = ItemsFolder:FindFirstChild(name); if not item then return nil end
        local tex
        pcall(function() tex = item.Texture or item.Image end)
        if tex and tex ~= "" then
            local id = extractAssetId(tex)
            if id then return ("rbxthumb://type=Asset&id=%s&w=420&h=420"):format(id) end
        end
        return nil
    end

        function CreateModernESP(parent, idName, config)
        local b = parent:FindFirstChild(idName)
        if not b then
            b = Instance.new("BillboardGui")
            b.Name = idName; b.Parent = parent; b.AlwaysOnTop = true
            b.Size = UDim2.new(0, 200, 0, 25)
            b.StudsOffset = Vector3.new(0, config.offsetY or 3.5, 0)

            local box = Instance.new("Frame")
            box.Name = "Box"; box.AutomaticSize = Enum.AutomaticSize.X
            box.Size = UDim2.new(0, 0, 0, 15); box.Position = UDim2.new(0.5, 0, 0, 0)
            box.AnchorPoint = Vector2.new(0.5, 0)
            box.BackgroundTransparency = 1
            box.BorderSizePixel = 0; box.ZIndex = 2; box.Parent = b

            local layout = Instance.new("UIListLayout", box)
            layout.FillDirection = Enum.FillDirection.Horizontal
            layout.VerticalAlignment = Enum.VerticalAlignment.Center
            layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
            layout.Padding = UDim.new(0, 3); layout.SortOrder = Enum.SortOrder.LayoutOrder

            local icon = Instance.new("ImageLabel", box)
            icon.Name = "Icon"; icon.Size = UDim2.new(0, 12, 0, 12)
            icon.BackgroundTransparency = 1; icon.ZIndex = 3; icon.LayoutOrder = 1; icon.Visible = false

            local txt = Instance.new("TextLabel", box)
            txt.Name = "Text"; txt.AutomaticSize = Enum.AutomaticSize.X
            txt.Size = UDim2.new(0, 0, 1, 0); txt.BackgroundTransparency = 1
            txt.Font = Enum.Font.GothamBlack
            txt.TextSize = 11; txt.ZIndex = 3
            txt.LayoutOrder = 2; txt.RichText = true
            txt.TextXAlignment = Enum.TextXAlignment.Center
            txt.TextYAlignment = Enum.TextYAlignment.Center
            txt.TextStrokeTransparency = 0
            txt.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        end

        local oldBox = b:FindFirstChild("Box")
        if oldBox then
            oldBox.BackgroundTransparency = 1
            local g = oldBox:FindFirstChildOfClass("UIGradient")
            if g then g:Destroy() end
            local p = oldBox:FindFirstChildOfClass("UIPadding")
            if p then p:Destroy() end
            local c = oldBox:FindFirstChildOfClass("UICorner")
            if c then c:Destroy() end
        end
        local oldLine = b:FindFirstChild("Line")
        if oldLine then oldLine.Visible = false end

        local iLbl = b.Box:FindFirstChild("Icon")
        if config.icon and config.icon ~= "" then
            if iLbl then iLbl.Image = config.icon; iLbl.Visible = true end
        else
            if iLbl then iLbl.Visible = false end
        end

        local col = config.color or Color3.fromRGB(255, 255, 255)
        local hex = string.format("#%02X%02X%02X",
            math.floor(col.R * 255), math.floor(col.G * 255), math.floor(col.B * 255))

        if config.distance then
            b.Box.Text.Text = string.format(
                "<font color='%s'><b>%s</b></font> <font color='#FFFFFF'>[%dm]</font>",
                hex, config.name, config.distance)
        elseif config.subtext then
            b.Box.Text.Text = string.format(
                "<font color='%s'><b>%s</b></font> <font color='#FFFFFF'>%s</font>",
                hex, config.name, config.subtext)
        else
            b.Box.Text.Text = string.format(
                "<font color='%s'><b>%s</b></font>",
                hex, config.name)
        end
    end

    function ClearESP(tipe)
        if tipe == "Player" then
            for _, p in pairs(_GetPlayers()) do
                if p.Character then
                    if p.Character:FindFirstChild("PEH") then p.Character.PEH:Destroy() end
                    if p.Character:FindFirstChild("PE_Text") then p.Character.PE_Text:Destroy() end
                end
            end
        elseif tipe == "Killer" then
            for _, p in pairs(_GetPlayers()) do
                if p.Character then
                    if p.Character:FindFirstChild("KEH") then p.Character.KEH:Destroy() end
                    if p.Character:FindFirstChild("KE_Text") then p.Character.KE_Text:Destroy() end
                end
            end
        elseif tipe == "Generator" then
            for _, v in pairs(Cache.Generators) do
                if v.model and v.model.Parent then
                    if v.model:FindFirstChild("GEH") then v.model.GEH:Destroy() end
                    if v.model:FindFirstChild("GE_Text") then v.model.GE_Text:Destroy() end
                end
            end
        elseif tipe == "Pallet" then
            for _, v in pairs(Cache.Pallets) do
                if v and v.Parent and v:FindFirstChild("PalletEH") then v.PalletEH:Destroy() end
            end
        elseif tipe == "Hook" then
            for _, v in pairs(Cache.Hooks) do
                if v and v.Parent and v:FindFirstChild("HookEH") then v.HookEH:Destroy() end
            end
        elseif tipe == "Window" then
            for _, v in pairs(Cache.Windows) do
                if v and v.Parent and v:FindFirstChild("WindowEH") then v.WindowEH:Destroy() end
            end
        elseif tipe == "Gate" then
            for _, v in pairs(Cache.Gates) do
                if v and v.Parent and v:FindFirstChild("GateEH") then v.GateEH:Destroy() end
            end
        elseif tipe == "SCP" then
            for _, v in pairs(Cache.SCPs) do
                if v and v.Parent and v:FindFirstChild("SCPEH") then v.SCPEH:Destroy() end
            end
        end
    end
    function ClearAllESP()
    ClearESP("Player"); ClearESP("Killer"); ClearESP("Generator")
    ClearESP("Pallet"); ClearESP("Hook"); ClearESP("Gate")
    ClearESP("SCP"); ClearESP("Window"); ClearHookESP()
end

    function UpdatePlayerESP()
        if not Config.ESP_Master then return end
        local myChar = LocalPlayer.Character
        local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if Config.ESP_KillerWarn and myHRP and GetRole() == "Survivor" then
            local warn = myHRP:FindFirstChild("KillerWarn")
            local closestDist = math.huge
            for _, p in ipairs(_GetPlayers()) do
                if p ~= LocalPlayer and IsKiller(p) and p.Character then
                    local kHrp = p.Character:FindFirstChild("HumanoidRootPart")
                    if kHrp then
                        local d = (kHrp.Position - myHRP.Position).Magnitude
                        if d < closestDist then closestDist = d end
                    end
                end
            end
            if closestDist <= 80 then
                if not warn then
                    warn = Instance.new("BillboardGui")
                    warn.Name = "KillerWarn"
                    warn.Size = UDim2.new(0, 30, 0, 30); warn.AlwaysOnTop = true
                    warn.StudsOffset = Vector3.new(0, 4, 0); warn.Parent = myHRP
                    local txt = Instance.new("TextLabel")
                    txt.Name = "WarnText"; txt.Size = UDim2.new(1,0,1,0)
                    txt.BackgroundTransparency = 1; txt.TextScaled = true
                    txt.TextStrokeTransparency = 0; txt.Font = Enum.Font.GothamBlack
                    txt.Parent = warn
                end
                local txt = warn:FindFirstChild("WarnText")
                if txt then
                    if closestDist <= 40 then txt.Text = "!!"; txt.TextColor3 = Color3.fromRGB(255,0,0)
                    else txt.Text = "!"; txt.TextColor3 = Color3.fromRGB(255,255,0) end
                end
            else
                if warn then warn:Destroy() end
            end
        else
            local warn = myHRP and myHRP:FindFirstChild("KillerWarn")
            if warn then warn:Destroy() end
        end
        if Config.ESP_Player or Config.ESP_Killer then
            for _, p in pairs(_GetPlayers()) do
                if p ~= LocalPlayer and p.Character then
                    local kStat = IsKiller(p)
                    local root = p.Character:FindFirstChild("Head")
                    if root and ((not kStat and Config.ESP_Player) or (kStat and Config.ESP_Killer)) then
                        local distance = myHRP and math.floor((root.Position - myHRP.Position).Magnitude) or 0
                        local col = kStat and Tuning.Colors.Killer or Tuning.Colors.Player
                        local hName = kStat and "KEH" or "PEH"
                        local tName = kStat and "KE_Text" or "PE_Text"
                        local hl = p.Character:FindFirstChild(hName)
                        if not hl then hl = Instance.new("Highlight"); hl.Name = hName; hl.Parent = p.Character end
                        hl.FillColor = col; hl.OutlineColor = col
                        hl.FillTransparency = Config.ESP_Outline and 1 or 0.5
                        hl.OutlineTransparency = 0
                        if Config.ESP_Name then
                            local eIcon = nil
                            if Config.ESP_ItemIcon and not kStat then
                                local eName = p:GetAttribute("EquippedItem")
                                if eName and eName ~= "" then eIcon = getItemIcon(eName) end
                            end
                            CreateModernESP(p.Character, tName, {
                                name = p.Name,
                                distance = Config.ESP_Distance and distance or nil,
                                color = col, icon = eIcon
                            })
                        else
                            local old = p.Character:FindFirstChild(tName)
                            if old then old:Destroy() end
                        end
                    end
                end
            end
        end
    end

    function UpdateSCPESP()
        if not Config.ESP_Master then return end
        if Config.ESP_SCP then
            for _, obj in ipairs(Cache.SCPs) do
                if obj and obj.Parent then
                    local hum = obj:FindFirstChildOfClass("Humanoid")
                    local root = obj:FindFirstChild("HumanoidRootPart") or obj:FindFirstChild("Torso") or obj.PrimaryPart
                    if hum and root and hum.Health > 0 and math.floor(hum.WalkSpeed) == 9 then
                        local col = Tuning.Colors.SCP
                        local hl = obj:FindFirstChild("SCPEH")
                        if not hl then hl = Instance.new("Highlight"); hl.Name = "SCPEH"; hl.Parent = obj end
                        hl.FillColor = col; hl.OutlineColor = col
                        hl.FillTransparency = Config.ESP_Outline and 1 or 0.5
                        hl.OutlineTransparency = 0
                    else
                        local h = obj:FindFirstChild("SCPEH")
                        if h then h:Destroy() end
                    end
                end
            end
        else ClearESP("SCP") end
    end

    function UpdateStaticESP()
        if not Config.ESP_Master then return end
        if Config.ESP_Generator then
            for _, vData in pairs(Cache.Generators) do
                local v = vData.model
                if v and v.Parent then
                    local progress = math.floor(v:GetAttribute("RepairProgress") or 0)
                    local col = (progress >= 100) and Tuning.Colors.GeneratorDone or Tuning.Colors.Generator
                    local h = v:FindFirstChild("GEH")
                    if not h then h = Instance.new("Highlight"); h.Name = "GEH"; h.Parent = v end
                    h.FillColor = col; h.OutlineColor = col
                    h.FillTransparency = Config.ESP_Outline and 1 or 0.5
                    h.OutlineTransparency = 0
                    if Config.ESP_GeneratorName then
                        local sub = progress >= 100 and "100%" or string.format("%d%%", progress)
                        CreateModernESP(v, "GE_Text", { name = "GEN", subtext = sub, color = col, icon = nil })
                    else
                        local old = v:FindFirstChild("GE_Text"); if old then old:Destroy() end
                    end
                end
            end
        end
        if Config.ESP_Pallet then
            for _, v in pairs(Cache.Pallets) do
                if v and v.Parent then
                    local h = v:FindFirstChild("PalletEH")
                    if not h then h = Instance.new("Highlight"); h.Name = "PalletEH"; h.Parent = v end
                    h.Adornee = v; h.FillColor = Tuning.Colors.Pallet; h.OutlineColor = Tuning.Colors.Pallet
                    h.FillTransparency = Config.ESP_Outline and 1 or 0.5; h.OutlineTransparency = 0
                end
            end
        end
        if Config.ESP_Window then
            for _, v in ipairs(Cache.Windows) do
                if v and v.Parent then
                    local tp = v:FindFirstChild("Bottom") or v:FindFirstChildWhichIsA("BasePart")
                    if tp then
                        local h = v:FindFirstChild("WindowEH")
                        if not h then
                            h = Instance.new("BoxHandleAdornment"); h.Name = "WindowEH"; h.Parent = v
                            h.AlwaysOnTop = true; h.ZIndex = 5
                        end
                        h.Adornee = tp; h.Size = tp.Size; h.Color3 = Tuning.Colors.Window
                        h.Transparency = Config.ESP_Outline and 0.8 or 0.4
                    end
                end
            end
        end
        if Config.ESP_Hook then
            for _, v in ipairs(Cache.Hooks) do
                if v and v.Parent then
                    local h = v:FindFirstChild("HookEH")
                    if not h then h = Instance.new("Highlight"); h.Name = "HookEH"; h.Parent = v end
                    h.FillColor = Tuning.Colors.Hook; h.OutlineColor = Tuning.Colors.Hook
                    h.FillTransparency = Config.ESP_Outline and 1 or 0.5; h.OutlineTransparency = 0
                end
            end
        end
        if Config.ESP_Gate then
            for _, v in ipairs(Cache.Gates) do
                if v and v.Parent then
                    local h = v:FindFirstChild("GateEH")
                    if not h then h = Instance.new("Highlight"); h.Name = "GateEH"; h.Parent = v end
                    h.Adornee = v; h.FillColor = Tuning.Colors.Gate; h.OutlineColor = Tuning.Colors.Gate
                    h.FillTransparency = Config.ESP_Outline and 1 or 0.5; h.OutlineTransparency = 0
                end
            end
        end
    end

    function ForceRefreshMap()
        ScanMap()
        if Config.ESP_Master then
            ClearAllESP()
            task.wait(0.1)
            UpdatePlayerESP(); UpdateSCPESP(); UpdateStaticESP()
        end
    end

    task.spawn(function() task.wait(2); ScanMap() end)
    LocalPlayer.CharacterAdded:Connect(function()
        task.wait(1.5); ScanMap()
        if Config.ESP_Master then
            task.spawn(function()
                task.wait(0.5); ClearAllESP(); task.wait(0.2)
                UpdatePlayerESP(); UpdateSCPESP(); UpdateStaticESP()
            end)
        end
    end)
