    function GetKillerUI()
        local pg = LocalPlayer:FindFirstChild("PlayerGui"); if not pg then return nil end
        for _, gui in pairs(pg:GetChildren()) do
            if string.sub(gui.Name, -4) == "-mob" and gui.Name ~= "Survivor-mob" then return gui end
        end
        return nil
    end
    local currentTouchInput = nil
    local isHoldingAbyssal = false
    local currentTouchAbyssalInput = nil
    function FireAbyssalSkill()
        if GetRole() ~= "Killer" then return end
        local sk = LocalPlayer:FindFirstChild("SelectedKiller")
        local kn = sk and sk.Value or LocalPlayer:GetAttribute("SelectedKiller")
        if string.find(string.lower(tostring(kn)), "abyss") then
            pcall(function() ReplicatedStorage.Remotes.Killers.Abysswalker.corrupt:FireServer() end)
        end
    end
    function StartInfiniteAbyssal()
        if isHoldingAbyssal then return end
        isHoldingAbyssal = true
        task.spawn(function()
            while isHoldingAbyssal and Config.Killer_InfAbyssal and GetRole() == "Killer" do
                FireAbyssalSkill(); task.wait(0.5)
            end
        end)
    end
    function StopInfiniteAbyssal() isHoldingAbyssal = false end

    UserInputService.InputBegan:Connect(function(input, gp)
        local isTouch = (input.UserInputType == Enum.UserInputType.Touch)
        local myRole = GetRole()
        if Config.Killer_InfAbyssal and input.KeyCode == Enum.KeyCode.Q then StartInfiniteAbyssal() end
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            if gp then return end
            if myRole == "Killer" and Config.Killer_Aimbot_Enabled then
                lockedAimbotTarget = getBestAimbotTarget()
                if lockedAimbotTarget then isAimbotHolding = true end
            end
        end
        if isTouch then
            if Config.Killer_InfAbyssal then
                local kUI = GetKillerUI()
                local m1 = kUI and kUI:FindFirstChild("Controls") and kUI.Controls:FindFirstChild("move2")
                if m1 and m1.Visible then
                    local pos = input.Position; local ap = m1.AbsolutePosition; local as = m1.AbsoluteSize
                    if pos.X >= ap.X and pos.X <= (ap.X + as.X) and pos.Y >= ap.Y and pos.Y <= (ap.Y + as.Y) then
                        StartInfiniteAbyssal(); currentTouchAbyssalInput = input
                    end
                end
            end
            if myRole == "Killer" and Config.Killer_Aimbot_Enabled then
                local kUI = GetKillerUI()
                local atk = kUI and kUI:FindFirstChild("Controls") and kUI.Controls:FindFirstChild("attack")
                if atk and atk.Visible then
                    local pos = input.Position; local ap = atk.AbsolutePosition; local as = atk.AbsoluteSize
                    if pos.X >= ap.X and pos.X <= (ap.X + as.X) and pos.Y >= ap.Y and pos.Y <= (ap.Y + as.Y) then
                        lockedAimbotTarget = getBestAimbotTarget()
                        if lockedAimbotTarget then isAimbotHolding = true; currentTouchInput = input end
                    end
                end
            end
        end
    end)
    UserInputService.InputEnded:Connect(function(input, gp)
        local isTouchEnd = (input.UserInputType == Enum.UserInputType.Touch)
        if input.KeyCode == Enum.KeyCode.Q then StopInfiniteAbyssal() end
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            isAimbotHolding = false; lockedAimbotTarget = nil
        end
        if isTouchEnd and input == currentTouchAbyssalInput then
            StopInfiniteAbyssal(); currentTouchAbyssalInput = nil
        end
        if isTouchEnd and input == currentTouchInput then
            isAimbotHolding = false; lockedAimbotTarget = nil; currentTouchInput = nil
        end
    end)

    -- ============ SILENT AIM INPUT HANDLERS ============
    UserInputService.InputBegan:Connect(function(input, gp)
        local isTouch = (input.UserInputType == Enum.UserInputType.Touch)
        if gp and not isTouch then return end
        local char = player.Character
        local isSpearMode = char and char:GetAttribute("spearmode") == true
        if input.UserInputType == Enum.UserInputType.MouseButton2 then
            if AimConfig.Aim_Silent then isChargingPistol = true; lockedTarget = getPistolTarget() end
            if AimConfig.Flash_Silent then isAimingFlash = true end
        elseif input.UserInputType == Enum.UserInputType.MouseButton1 then
            if AimConfig.Aim_Silent and isChargingPistol then executeSilentAimFire() end
            if IsVeilSilentOn() and isSpearMode then isChargingSpear = true end
        elseif isTouch then
            if AimConfig.Aim_Silent or AimConfig.Flash_Silent then
                local pg = player:FindFirstChild("PlayerGui")
                if pg then
                    local sm = pg:FindFirstChild("Survivor-mob")
                    if sm then
                        local cc = sm:FindFirstChild("Controls")
                        if cc then
                            local tb = cc:FindFirstChild("Gui-mob")
                            if tb and tb.Visible then
                                local pos = input.Position; local ap = tb.AbsolutePosition; local as = tb.AbsoluteSize
                                if pos.X >= ap.X and pos.X <= (ap.X + as.X) and pos.Y >= ap.Y and pos.Y <= (ap.Y + as.Y) then
                                    if AimConfig.Aim_Silent then isChargingPistol = true; currentTouchInput = input; lockedTarget = getPistolTarget() end
                                    if AimConfig.Flash_Silent then isAimingFlash = true; currentTouchInput = input end
                                end
                            end
                        end
                    end
                end
            end
            if IsVeilSilentOn() and isSpearMode then
                local pg = player:FindFirstChild("PlayerGui")
                if pg then
                    local sm = pg:FindFirstChild("Slasher-mob")
                    if sm then
                        local cc = sm:FindFirstChild("Controls")
                        if cc then
                            local atk = cc:FindFirstChild("attack")
                            if atk and atk.Visible then
                                local pos = input.Position; local ap = atk.AbsolutePosition; local as = atk.AbsoluteSize
                                if pos.X >= ap.X and pos.X <= (ap.X + as.X) and pos.Y >= ap.Y and pos.Y <= (ap.Y + as.Y) then
                                    isChargingSpear = true; currentTouchInput = input
                                end
                            end
                        end
                    end
                end
            end
        end
    end)
    UserInputService.InputEnded:Connect(function(input, gp)
        local isTouchEnd = (input.UserInputType == Enum.UserInputType.Touch)
        if input.UserInputType == Enum.UserInputType.MouseButton2 then
            if isChargingPistol then isChargingPistol = false; lockedTarget = nil end
            if isAimingFlash then isAimingFlash = false end
        end
        if isChargingSpear and (input == currentTouchInput or input.UserInputType == Enum.UserInputType.MouseButton1) then
            isChargingSpear = false
            if currentTouchInput == input then currentTouchInput = nil end
            if isAttackCooldown then return end
            isAttackCooldown = true
            task.delay(2, function() isAttackCooldown = false end)
            local myChar = LocalPlayer.Character
            local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
            local startPart = myChar and (myChar:FindFirstChild("Head") or myHRP)
            if startPart and myHRP then
                local isSpecial = myChar:GetAttribute("special") == true
                local startPos = Config.SpearSmart_enable and myHRP.Position or startPart.Position
                local curSpeed = Config.SpearSmart_enable and (isSpecial and 165 or 142.5) or AimConfig.SPEAR_Speed
                local tp = getClosestSurvivor()
                local aimDir
                if tp then
                    local tHRP = tp:IsA("Model") and tp:FindFirstChild("HumanoidRootPart") or tp
                    local tPos = tHRP.Position
                    local tVel = Vector3.new(0, 0, 0)
                    local tHum = tp.Parent and tp.Parent:FindFirstChildOfClass("Humanoid")
                    if tHum and tHum.MoveDirection.Magnitude > 0 then tVel = tHum.MoveDirection * tHum.WalkSpeed
                    elseif tHRP:IsA("BasePart") then tVel = tHRP.AssemblyLinearVelocity end
                    tVel = Vector3.new(tVel.X, 0, tVel.Z)
                    local d = (tPos - startPos).Magnitude
                    local tth = d / curSpeed
                    if Config.SpearSmart_enable then
                        local g = workspace.Gravity * 0.5
                        local lm = AimConfig.Veil_LeadMultiplier
                        local pp = tPos + (tVel * (tth * lm))
                        local drop = 0.5 * g * (tth ^ 2)
                        local fap = pp + Vector3.new(0, drop - 1.5, 0)
                        aimDir = (fap - startPos).Unit
                    else
                        local dp = math.clamp(d / 50, 0.1, 4.0)
                        local pp = tPos + (tVel * (tth * dp))
                        local dm = math.clamp(d / 100, 1, 2.5)
                        local ag = math.max(0, d - 8)
                        local g = AimConfig.AIM_Auto and ag or AimConfig.SPEAR_Gravity
                        local drop = 0.5 * g * (tth ^ 2) * dm
                        local fap = pp + Vector3.new(0, drop, 0)
                        aimDir = (fap - startPos).Unit
                    end
                else
                    aimDir = Camera.CFrame.LookVector
                end
                if AimConfig.Aim_SilentVeil then
                    pcall(function()
                        ReplicatedStorage.Remotes.Killers.Veil.Spearthrow:FireServer(aimDir, curSpeed, startPos)
                    end)
                end
            end
        end
        if isTouchEnd and input == currentTouchInput then
            if isChargingPistol then
                isChargingPistol = false; currentTouchInput = nil
                executeSilentAimFire(); lockedTarget = nil
            end
            if isAimingFlash then isAimingFlash = false; currentTouchInput = nil end
        end
    end)

