    local RepairEvent = game:GetService("ReplicatedStorage").Remotes.Generator.RepairEvent
    local GenCache = {}; local GenCacheTimer = 0
    function GetAllGenerators()
        local now = tick()
        if now - GenCacheTimer < 5 then return GenCache end
        GenCache = {}; GenCacheTimer = now
        local mf = workspace:FindFirstChild("Map"); if not mf then return GenCache end
        pcall(function()
            for _, v in pairs(mf:GetDescendants()) do
                if not v:IsA("Model") then continue end
                if v.Name ~= "Generator" then continue end
                local isReal = v:GetAttribute("RepairProgress") ~= nil
                    or v:GetAttribute("kickcount") ~= nil
                    or v:GetAttribute("ProgressRepair") ~= nil
                if not isReal then continue end
                table.insert(GenCache, v)
            end
        end)
        return GenCache
    end
    PlayRepairAnim = function()
        local char = LocalPlayer.Character; if not char then return end
        local hum = char:FindFirstChildOfClass("Humanoid")
        local an = hum and hum:FindFirstChildOfClass("Animator")
        if not an then return end
        if RepairAnimTrack and RepairAnimTrack.IsPlaying then return end
        pcall(function()
            local a = Instance.new("Animation")
            a.AnimationId = "rbxassetid://92960319113695"
            RepairAnimTrack = an:LoadAnimation(a)
            RepairAnimTrack.Priority = Enum.AnimationPriority.Action
            RepairAnimTrack:Play()
        end)
    end
    StopRepairAnim = function()
        if RepairAnimTrack and RepairAnimTrack.IsPlaying then
            pcall(function() RepairAnimTrack:Stop() end)
        end
        RepairAnimTrack = nil
    end
    GetGeneratorPoints = function(genModel)
        local points = {}
        pcall(function()
            for _, obj in pairs(genModel:GetChildren()) do
                if obj.Name:find("GeneratorPoint") and obj:IsA("BasePart") then table.insert(points, obj) end
            end
        end)
        return points
    end
    StopAutoRepair = function()
        StopRepairAnim()
        local pt = AutoCurrentPoint; AutoCurrentPoint = nil
        if pt then pcall(function() RepairEvent:FireServer(pt, false) end) end
    end
    StartAutoRepairLoop = function(genModel)
        AutoCurrentGenModel = genModel
        if AutoRepairThread then task.cancel(AutoRepairThread); AutoRepairThread = nil end
        StopAutoRepair()
        AutoRepairThread = task.spawn(function()
            while AutoRepairEnabled and BypassGenEnabled do
                local char = LocalPlayer.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                if not hrp then task.wait(0.1); continue end
                local found = nil
                for _, gen in pairs(GetAllGenerators()) do
                    for _, p in pairs(GetGeneratorPoints(gen)) do
                        if (hrp.Position - p.Position).Magnitude <= 5 then found = p; break end
                    end
                    if found then break end
                end
                if found then
                    AutoCurrentPoint = found
                    local now = tick()
                    if now - LastFireTime >= AutoFireInterval then
                        PlayRepairAnim()
                        pcall(function() RepairEvent:FireServer(found, true) end)
                        LastFireTime = now
                    end
                else
                    if AutoCurrentPoint then
                        StopAutoRepair(); AutoRepairEnabled = false
                        if AutoCurrentGenModel then ProcessedGens[AutoCurrentGenModel] = nil; AutoCurrentGenModel = nil end
                        break
                    end
                end
                task.wait(0.1)
            end
            StopAutoRepair()
        end)
    end
    waitForRepairing = function(point, timeout)
        local s = tick()
        while tick() - s < (timeout or 1) do
            if point:GetAttribute("IsRepairing") == true then return true end
            task.wait(0.05)
        end
        return false
    end
