                if myH and kH and (myH.Position - kH.Position).Magnitude <= 40 then TriggerCrouch() end
                return
            end
            if not Config.Surv_AutoParry then return end
            if State.ParryCooldown then return end
            if Config.Ignored_Skills_List and Config.Ignored_Skills_List[aName] then return end
            local myC = LocalPlayer.Character
            if IsDowned(myC) or not IsSafeToParry(myC) then return end
            local myH = myC and myC:FindFirstChild("HumanoidRootPart")
            local kH = kChar:FindFirstChild("HumanoidRootPart")
            if not myH or not kH then return end
            local delta = myH.Position - kH.Position
            local sd = delta.Magnitude
            
            -- ⭐ ANTI FAKE HIT 
if Config.Surv_ParryAntiFake ~= false then
    if not IsKillerFacingMe(kChar, myH.Position, Config.Surv_ParryFacingAngle or 60) then
        return
    end
end

            if Config.Surv_ParryAggressive then
                local ar = 12; local dr = Config.Surv_ParryRadius + 5
                if sd > dr then return end
                if sd <= ar then ExecuteParry()
                else
                    local tracker
                    local st = os.clock()
                    tracker = RunService.Heartbeat:Connect(function()
                        if os.clock() - st >= 1.5 or State.ParryCooldown or not myH or not kH or IsDowned(myC) then
                            if tracker then tracker:Disconnect() end
                            return
                        end
                        if _frameCounter % 2 == 0 then
                            if (myH.Position - kH.Position).Magnitude <= ar then
                                ExecuteParry(); if tracker then tracker:Disconnect() end
                            end
                        end
                    end)
                end
            else
                if sd > Config.Surv_ParryRadius then return end
                local mpf = Vector3.new(myH.Position.X, 0, myH.Position.Z)
                local kpf = Vector3.new(kH.Position.X, 0, kH.Position.Z)
                local fd = mpf - kpf
                if fd.Magnitude > 0 then
                    local fdir = fd.Unit
                    local klf = Vector3.new(kH.CFrame.LookVector.X, 0, kH.CFrame.LookVector.Z).Unit
                    if klf:Dot(fdir) < Config.Surv_ParryFace then return end
                end
                ExecuteParry()
            end
        end)
    end
