            "ColorCorrectionEffect", "DepthOfFieldEffect",
            "BlurEffect", "SunRaysEffect", "BloomEffect"
        }
        for _, v in pairs(Lighting:GetChildren()) do
            for _, t in pairs(ScreenEffectTypes) do
                if v:IsA(t) then
                    DisabledEffects[v] = v.Enabled
                    v.Enabled = false
                end
            end
        end
    end

