        if renderLoop then renderLoop:Disconnect(); renderLoop = nil end
        local e = LocalPlayer.Character
        local c = e and e:FindFirstChildOfClass("Humanoid")
        if c then c.AutoRotate = true end
    end
    local function initializeMovement()
        terminateMovement()
