    -- ============ AUTO DROP PALLET ============
    AutoPalletEnabled = false
    AutoPalletSafety = true
    AutoPalletDistance = 10
    local _lastPalletDrop = 0
    local _usedPallets = {}
    local _autoPalletConn = nil
    function GetKillerRoot()
        for _, plr in ipairs(_GetPlayers()) do
            if plr == LocalPlayer then continue end
            if plr.Team and plr.Team.Name == "Survivors" then continue end
            local c = plr.Character
            if c then local r = c:FindFirstChild("HumanoidRootPart"); if r then return r end end
        end
        return nil
    end
    function IsSafeToDropPallet(char)
        if not AutoPalletSafety then return true end
        if not char then return false end
        if char:GetAttribute("Knocked") == true then return false end
        if char:GetAttribute("IsCarried") == true then return false end
        if char:GetAttribute("IsHooked") == true then return false end
        local i = char:FindFirstChild("CheckInterractable")
        if i then
            if i:GetAttribute("isVaulting") or i:GetAttribute("isRepairing")
            or i:GetAttribute("isUnhooking") or i:GetAttribute("isHealing")
            or i:GetAttribute("isSliding") or i:GetAttribute("isCarrying") then return false end
        end
        local h = char:FindFirstChildOfClass("Humanoid")
        if h and h.Health <= 0 then return false end
        return true
    end
    function FindNearestPallet(myRoot)
        local bp, bd = nil, AutoPalletDistance
        for _, pallet in ipairs(Cache.Pallets or {}) do
            if not pallet or not pallet.Parent then continue end
            if _usedPallets[pallet] then continue end
            local rp = pallet:FindFirstChild("PrimaryPartPallet") or pallet:FindFirstChild("PalletPoint")
                or pallet:FindFirstChild("PalletPointSlide") or pallet:FindFirstChildWhichIsA("BasePart")
            if not rp then continue end
            local ok, pos = pcall(function() return rp.Position end)
            if not ok or not pos then continue end
            local d = (myRoot.Position - pos).Magnitude
            if d < bd then bd = d; bp = pallet end
        end
        return bp
    end
    function DropPallet(pallet)
        if not pallet then return false end
        local t = pallet:FindFirstChild("PalletPointSlide") or pallet:FindFirstChild("PalletPoint") or pallet:FindFirstChildWhichIsA("BasePart")
        if not t then return false end
        local r = ReplicatedStorage:FindFirstChild("Remotes")
        local de = r and r:FindFirstChild("Pallet") and r.Pallet:FindFirstChild("PalletDropEvent")
        if de then
            pcall(function() de:FireServer(t) end)
            _usedPallets[pallet] = true; _lastPalletDrop = tick()
            return true
        end
        return false
    end
    function StartAutoPallet()
        if _autoPalletConn then return end
        _autoPalletConn = task.spawn(function()
            while AutoPalletEnabled do
                task.wait(0.4)
                if GetRole() ~= "Survivor" then continue end
                if tick() - _lastPalletDrop < 2.5 then continue end
                pcall(function()
                    local char = LocalPlayer.Character
                    local mr = char and char:FindFirstChild("HumanoidRootPart")
                    local h = char and char:FindFirstChildOfClass("Humanoid")
                    if not mr or not h or h.Health <= 0 then return end
                    if not IsSafeToDropPallet(char) then return end
                    local kr = GetKillerRoot(); if not kr then return end
                    if (mr.Position - kr.Position).Magnitude > AutoPalletDistance then return end
                    local p = FindNearestPallet(mr)
                    if p then DropPallet(p) end
                end)
            end
        end)
    end
    function StopAutoPallet()
        if _autoPalletConn then task.cancel(_autoPalletConn); _autoPalletConn = nil end
    end
    LocalPlayer.CharacterAdded:Connect(function()
        _usedPallets = {}; _lastPalletDrop = 0
    end)

    -- ============ RENDER STEPPED LOOP (OPTIMIZED - THROTTLED) ============
    RunService.RenderStepped:Connect(function()
        _frameCounter = _frameCounter + 1
        if _frameCounter > 1000000 then _frameCounter = 0 end

    drawCrosshair()

        local char = player.Character; if not char then return end
        local hrp = char:FindFirstChild("HumanoidRootPart")
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hrp or not hum then return end
        local currentTime = tick()

        if Config.Surv_Aimbot_Enabled then
            local myRole = GetRole()
            if myRole == "Survivor" then
                local t = getBestAimbotTarget()
                if t then
                    local tp = t.Position
                    local d = GetDistance(tp)
                    if d < 100 then
                        local dd = 100 - d
                        local ro = dd * Config.Surv_Aimbot_Predict
                        tp = tp + (Camera.CFrame.RightVector * ro)
                    end
                    local g = CFrame.new(Camera.CFrame.Position, tp)
                    Camera.CFrame = Camera.CFrame:Lerp(g, Config.Surv_Aimbot_Smoothness)
                    local gh = CFrame.new(hrp.Position, Vector3.new(tp.X, hrp.Position.Y, tp.Z))
                    hrp.CFrame = hrp.CFrame:Lerp(gh, Config.Surv_Aimbot_Smoothness)
                end
            end
        end

        if Config.Killer_Aimbot_Enabled and isAimbotHolding then
            local myRole = GetRole()
            if myRole == "Killer" and lockedAimbotTarget then
                local tc = lockedAimbotTarget.Parent
                local th = tc and tc:FindFirstChild("Humanoid")
                if not th or th.Health <= 0 or IsDowned(tc) then lockedAimbotTarget = getBestAimbotTarget() end
                if lockedAimbotTarget then
                    local tp = lockedAimbotTarget.Position
                    if GetDistance(tp) > Config.Killer_Aimbot_MaxDist then lockedAimbotTarget = getBestAimbotTarget()
                    else
                        local g = CFrame.new(Camera.CFrame.Position, tp)
                        Camera.CFrame = Camera.CFrame:Lerp(g, Config.Killer_Aimbot_Smoothness)
                        local gh = CFrame.new(hrp.Position, Vector3.new(tp.X, hrp.Position.Y, tp.Z))
                        hrp.CFrame = hrp.CFrame:Lerp(gh, Config.Killer_Aimbot_Smoothness)
                    end
                end
            end
        end

        if _frameCounter % 3 == 0 then
            local isSpearMode = char and char:GetAttribute("spearmode") == true
            if IsVeilSilentOn() and AimConfig.Veil_ShowFOV and isSpearMode then
                VeilFOVFrame.Visible = true
                VeilFOVFrame.Size = UDim2.new(0, AimConfig.Veil_FOV*2, 0, AimConfig.Veil_FOV*2)
            else VeilFOVFrame.Visible = false end

            do
                local cam = workspace.CurrentCamera
                local canShow = IsVeilSilentOn() and isSpearMode and cam
                if canShow then
                    local tp = getClosestSurvivor()
                    if tp and tp.Parent then
                        veilTargetHighlight.Parent = tp.Parent
                        if VeilTrackerEnabled then
                            if not currentVeilBillboard or currentVeilBillboard.Parent ~= tp then
                                if currentVeilBillboard then currentVeilBillboard:Destroy() end
                                currentVeilBillboard = makeVeilBillboard()
                                currentVeilBillboard.Adornee = tp
                                currentVeilBillboard.Parent = tp
                            end
                            local sp, on = cam:WorldToViewportPoint(tp.Position)
                            if on and sp.Z > 0 then
                                local vp = cam.ViewportSize
                                local fx = vp.X*0.5; local fy = vp.Y
                                local tx, ty = sp.X, sp.Y
                                local dx, dy = tx-fx, ty-fy
                                local l = math.sqrt(dx*dx+dy*dy)
                                VeilTrackerLine.Size = UDim2.fromOffset(math.max(l, 1), 1)
                                VeilTrackerLine.Position = UDim2.fromOffset((fx+tx)*0.5, (fy+ty)*0.5)
                                VeilTrackerLine.Rotation = math.deg(math.atan2(dy, dx))
                                VeilTrackerLine.Visible = true
                            else VeilTrackerLine.Visible = false end
                        else
                            if currentVeilBillboard then currentVeilBillboard:Destroy(); currentVeilBillboard = nil end
                            VeilTrackerLine.Visible = false
                        end
                    else
                        veilTargetHighlight.Parent = nil
                        if currentVeilBillboard then currentVeilBillboard:Destroy(); currentVeilBillboard = nil end
                        VeilTrackerLine.Visible = false
                    end
                else
                    veilTargetHighlight.Parent = nil
                    if currentVeilBillboard then currentVeilBillboard:Destroy(); currentVeilBillboard = nil end
                    VeilTrackerLine.Visible = false
                end
            end
        end

        if isAimingFlash and AimConfig.Flash_Silent then
            local tp = getKillerTargetForFlash()
            if tp then
                local myChar = LocalPlayer.Character
                local mh = myChar and myChar:FindFirstChild("HumanoidRootPart")
                local tpos = tp.Position + Vector3.new(0, AimConfig.Flash_YOffset, 0)
                local cam = workspace.CurrentCamera
                cam.CFrame = cam.CFrame:Lerp(CFrame.lookAt(cam.CFrame.Position, tpos), 0.5)
                if mh then
                    local g = CFrame.lookAt(mh.Position, Vector3.new(tpos.X, mh.Position.Y, tpos.Z))
                    mh.CFrame = mh.CFrame:Lerp(g, 0.5)
                end
            end
        end

        if MoonwalkEnabled then
            local vp = workspace.CurrentCamera
            if vp then
                local f = vp.CFrame.LookVector
                local s = vp.CFrame.RightVector
                local nl = Vector3.new(f.X, 0, f.Z)
                local nr = Vector3.new(s.X, 0, s.Z)
                if nl.Magnitude > 0.001 then nl = nl.Unit end
                if nr.Magnitude > 0.001 then nr = nr.Unit end
                local wp = math.sin(currentTime * 35)
                local ca = math.rad(30 * wp)
                local rl = CFrame.Angles(0, ca, 0) * nl
                hrp.CFrame = CFrame.lookAt(hrp.Position, hrp.Position + rl)
                local bv = -nl * 1.2
                local sv = nr * (wp * 1.05)
                hum:Move(bv + sv, false)
            end
        end

        if _frameCounter % 3 == 0 then
            if Auto.SkillCheck and not State.busy then
                local prompt = PlayerGui:FindFirstChild("SkillCheckPromptGui")
                if prompt then
                    local check = prompt:FindFirstChild("Check")
                    if check and check.Visible then
                        local line = check:FindFirstChild("Line")
                        local goal = check:FindFirstChild("Goal")
                        if line and goal then
                            if Auto.SkillCheckMode == "Instant" then
                                line.Rotation = goal.Rotation + 109
                                State.busy = true
                                task.spawn(function() TriggerSkillCheck(); task.wait(0.05); State.busy = false end)
                            else
                                local lr = line.Rotation % 360
                                local gr = goal.Rotation % 360
                                local sR, eR
                                if Auto.SkillCheckMode == "Normal" then
                                    sR = (gr + 116) % 360; eR = (gr + 140) % 360
                                else sR = (gr + 102) % 360; eR = (gr + 116) % 360 end
                                local inZ = false
                                if sR > eR then inZ = (lr >= sR or lr <= eR)
                                else inZ = (lr >= sR and lr <= eR) end
                                if inZ then
                                    State.busy = true
                                    task.spawn(function() TriggerSkillCheck(); task.wait(0.05); State.busy = false end)
                                end
                            end
                        end
                    end
                end
            end
        end
    end)
    -- =======================================================================

    -- ============ HEARTBEAT LOOP (OPTIMIZED) ============
    local lastEspUpdate = 0
    local lastNoSlowdown = 0
    local lastFleeTime = 0
    RunService.Heartbeat:Connect(function()
        local char = player.Character; if not char then return end
        local hrp = char:FindFirstChild("HumanoidRootPart")
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hrp or not hum then return end
        local ct = tick()

        if _frameCounter % 2 == 0 then
            if SpeedInputEnabled then
                local md = hum.MoveDirection
                if md.Magnitude > 0 then hrp.CFrame = hrp.CFrame + (md * SpeedInputValue) end
            end
            if SpeedEnabled then
                local md = hum.MoveDirection
                if md.Magnitude > 0 then hrp.CFrame = hrp.CFrame + (md * SpeedAmount) end
            end
            if GodMode and hum and hum.Health < hum.MaxHealth then hum.Health = hum.MaxHealth end
            if FleeKillerEnabled and ct - lastFleeTime >= 0.3 then lastFleeTime = ct; FleeKiller() end
        end

        if _frameCounter % 5 == 0 then
            if Config.Surv_ParryCircle and Config.Surv_AutoParry and hrp then
                if not State.AutoParryAdornment or State.AutoParryAdornment.Parent ~= hrp then
                    if State.AutoParryAdornment then State.AutoParryAdornment:Destroy() end
                    State.AutoParryAdornment = Instance.new("CylinderHandleAdornment")
                    State.AutoParryAdornment.Name = "AutoParryCircleESP"
                    State.AutoParryAdornment.Height = 0.05
                    State.AutoParryAdornment.Transparency = 0.3
                    State.AutoParryAdornment.Adornee = hrp
                    State.AutoParryAdornment.Parent = hrp
                    State.AutoParryAdornment.ZIndex = 0
                    State.AutoParryAdornment.AlwaysOnTop = false
                end
                local cR = Config.Surv_ParryRadius
                State.AutoParryAdornment.Radius = cR
                State.AutoParryAdornment.InnerRadius = math.max(0.1, cR - 0.15)
                State.AutoParryAdornment.CFrame = CFrame.new(0, -3, 0) * CFrame.Angles(math.rad(90), 0, 0)
                if State.ParryCooldown then State.AutoParryAdornment.Color3 = Color3.fromRGB(255,128,0)
                elseif Config.Surv_ParryAggressive then State.AutoParryAdornment.Color3 = Color3.fromRGB(255,0,0)
                else State.AutoParryAdornment.Color3 = Color3.fromRGB(0,255,255) end
            elseif State.AutoParryAdornment then
                State.AutoParryAdornment:Destroy(); State.AutoParryAdornment = nil
            end
        end

        if NoSlowdownEnabled and ct - lastNoSlowdown >= 0.3 then
            lastNoSlowdown = ct
            local h2 = char:FindFirstChildOfClass("Humanoid")
            if h2 and GetRole() == "Killer" and h2.WalkSpeed < 16 then h2.WalkSpeed = 16 end
        end

        if Config.ESP_Master and ct - lastEspUpdate >= 5 then
            lastEspUpdate = ct
            if Config.ESP_Player or Config.ESP_Killer or Config.ESP_Name or Config.ESP_ItemIcon or Config.ESP_KillerWarn then UpdatePlayerESP() end
            if Config.ESP_SCP then UpdateSCPESP() end
            if Config.ESP_Generator or Config.ESP_Pallet or Config.ESP_Hook or Config.ESP_Gate or Config.ESP_Window then UpdateStaticESP() end
        end
    end)

    -- ============ CUSTOM PARRY GUI ============
    local AutoParryCustom = { Gui = nil, IsActive = false, GuiVisible = false }
    local function UpdateCustomParryGUI(isOn)
        if not AutoParryCustom.Gui then return end
        local f = AutoParryCustom.Gui:FindFirstChild("Frame"); if not f then return end
        local b = f:FindFirstChild("ActionButton")
        local s = f:FindFirstChild("UIStroke")
        if isOn then
            if b then b.Text = "PARRY [ON]"; b.TextColor3 = Color3.fromRGB(255, 255, 255); b.BackgroundColor3 = Color3.fromRGB(0, 0, 0) end
if s then s.Color = Color3.fromRGB(255, 255, 255) end
        else
            if b then b.Text = "PARRY [OFF]"; b.TextColor3 = Color3.fromRGB(255, 255, 255); b.BackgroundColor3 = Color3.fromRGB(0, 0, 0) end
if s then s.Color = Color3.fromRGB(255, 255, 255) end
        end
    end
    local function ToggleParryStatus()
        Config.Surv_AutoParry = not Config.Surv_AutoParry
        AutoParryCustom.IsActive = Config.Surv_AutoParry
        UpdateCustomParryGUI(Config.Surv_AutoParry)
        pcall(function() if UI.AutoParry then UI.AutoParry.Set(Config.Surv_AutoParry) end end)
    end
    local function CreateCustomParryGUI()
        if AutoParryCustom.Gui then AutoParryCustom.Gui:Destroy(); AutoParryCustom.Gui = nil end
        local gui = Instance.new("ScreenGui")
        gui.Name = "AutoParryCustomGui"; gui.ResetOnSpawn = false
        gui.IgnoreGuiInset = true; gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        gui.Parent = CoreGui; gui.Enabled = false
        AutoParryCustom.Gui = gui; AutoParryCustom.GuiVisible = false
        local f = Instance.new("Frame")
        f.Name = "Frame"; f.Parent = gui
        f.Size = UDim2.fromOffset(110, 36); f.Position = UDim2.fromScale(0.85, 0.35)
        f.BackgroundColor3 = Color3.fromRGB(25,25,30); f.BackgroundTransparency = 0.1
        f.Active = true; f.BorderSizePixel = 0
        Instance.new("UICorner", f).CornerRadius = UDim.new(0, 8)
        local s = Instance.new("UIStroke", f)
        s.Name = "UIStroke"; s.Color = Color3.fromRGB(90,90,95); s.Thickness = 1.5; s.Transparency = 0.2
        local b = Instance.new("TextButton")
        b.Name = "ActionButton"; b.Size = UDim2.new(1,0,1,0)
        b.Text = "PARRY [OFF]"; b.BackgroundColor3 = Color3.fromRGB(30,30,35)
        b.Font = Enum.Font.GothamBold; b.TextSize = 12
        b.TextColor3 = Color3.fromRGB(200,200,200); b.BorderSizePixel = 0
        b.AutoButtonColor = false; b.Parent = f
        Instance.new("UICorner", b).CornerRadius = UDim.new(0, 8)
        local dragging, dragMoved, canDrag = false, false, false
        local dragStart, startPos, holdThread = nil, nil, nil
        local DT, HT = 18, 0.18
        local function update(input)
            if not dragging or not canDrag or not dragStart or not startPos then return end
            local delta = input.Position - dragStart
            if not dragMoved and (math.abs(delta.X) > DT or math.abs(delta.Y) > DT) then dragMoved = true end
            if dragMoved then
                f.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
            end
        end
        b.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = true; dragMoved = false; canDrag = false
                dragStart = input.Position; startPos = f.Position
                if holdThread then task.cancel(holdThread) holdThread = nil end
                holdThread = task.delay(HT, function() if dragging then canDrag = true end end)
            end
        end)
        b.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                if holdThread then task.cancel(holdThread) holdThread = nil end
                if dragging and not dragMoved then ToggleParryStatus() end
                dragging = false; dragMoved = false; canDrag = false
                dragStart = nil; startPos = nil
            end
        end)
        UserInputService.InputChanged:Connect(function(input)
            if dragging and canDrag and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                update(input)
            end
        end)
        if AutoParryCustom._statusConn then AutoParryCustom._statusConn:Disconnect() end
        AutoParryCustom._statusConn = RunService.Heartbeat:Connect(function()
            if not AutoParryCustom.Gui or not AutoParryCustom.Gui.Parent then
                if AutoParryCustom._statusConn then AutoParryCustom._statusConn:Disconnect(); AutoParryCustom._statusConn = nil end
                return
