    -- ============ INVISIBILITY GUI ============
    local InvisCustom = { Gui = nil, IsActive = false, GuiVisible = false }
    local Invisible = nil
    local InvisibleLoading = false
    local function LoadInvisible()
        if Invisible then return true end
        if InvisibleLoading then return false end
        InvisibleLoading = true
        task.spawn(function()
            local s, e = pcall(function()
                loadstring(game:HttpGet("https://raw.githubusercontent.com/willrev-424/yore/refs/heads/main/wilrevv.lua"))()
            end)
            task.wait(1.2)
            if _G.MengHub and _G.MengHub.Invisible then
                Invisible = _G.MengHub.Invisible
            else
                warn("Gagal load Invisibility:", tostring(e))
            end
            InvisibleLoading = false
        end)
        return false
    end
    task.spawn(function() task.wait(2); LoadInvisible() end)
    local function UpdateCustomInvisGUI(isOn)
        if not InvisCustom.Gui then return end
        local f = InvisCustom.Gui:FindFirstChild("Frame"); if not f then return end
        local b = f:FindFirstChild("ActionButton")
        local s = f:FindFirstChild("UIStroke")
        if isOn then
            if b then b.Text = "INVIS [ON]"; b.TextColor3 = Color3.fromRGB(255, 255, 255); b.BackgroundColor3 = Color3.fromRGB(0, 0, 0) end
if s then s.Color = Color3.fromRGB(255, 255, 255) end
        else
            if b then b.Text = "INVIS [OFF]"; b.TextColor3 = Color3.fromRGB(255, 255, 255); b.BackgroundColor3 = Color3.fromRGB(0, 0, 0) end
if s then s.Color = Color3.fromRGB(255, 255, 255) end
        end
    end
    local function ToggleInvisStatus()
        if not Invisible then
            if InvisibleLoading then return end
            LoadInvisible(); task.wait(1.5)
            if not Invisible then return end
        end
        InvisCustom.IsActive = not InvisCustom.IsActive
        if InvisCustom.IsActive then pcall(function() Invisible.enable() end)
        else pcall(function() Invisible.disable() end) end
        UpdateCustomInvisGUI(InvisCustom.IsActive)
        pcall(function() if UI.InvisToggle then UI.InvisToggle.Set(InvisCustom.IsActive) end end)
    end
    local function CreateCustomInvisGUI()
        if InvisCustom.Gui then InvisCustom.Gui:Destroy(); InvisCustom.Gui = nil end
        local gui = Instance.new("ScreenGui")
        gui.Name = "InvisCustomGui"; gui.ResetOnSpawn = false
        gui.IgnoreGuiInset = true; gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        gui.Parent = CoreGui; gui.Enabled = false
        InvisCustom.Gui = gui; InvisCustom.GuiVisible = false
        local f = Instance.new("Frame")
        f.Name = "Frame"; f.Parent = gui
        f.Size = UDim2.fromOffset(110, 36); f.Position = UDim2.fromScale(0.85, 0.42)
        f.BackgroundColor3 = Color3.fromRGB(25,25,30); f.BackgroundTransparency = 0.1
        f.Active = true; f.BorderSizePixel = 0
        Instance.new("UICorner", f).CornerRadius = UDim.new(0, 8)
        local s = Instance.new("UIStroke", f)
        s.Name = "UIStroke"; s.Color = Color3.fromRGB(90,90,95); s.Thickness = 1.5; s.Transparency = 0.2
        local b = Instance.new("TextButton")
        b.Name = "ActionButton"; b.Size = UDim2.new(1,0,1,0)
        b.Text = "INVIS [OFF]"; b.BackgroundColor3 = Color3.fromRGB(30,30,35)
        b.Font = Enum.Font.GothamBold; b.TextSize = 12
        b.TextColor3 = Color3.fromRGB(200,200,200); b.BorderSizePixel = 0
        b.AutoButtonColor = false; b.Parent = f
        Instance.new("UICorner", b).CornerRadius = UDim.new(0, 8)
        local dragging, dragMoved, canDrag = false, false, false
        local dragStart, startPos, holdThread = nil, nil, nil
        local DT, HT = 18, 0.18
        local function update(input)
            if not dragging or not canDrag or not dragStart or not startPos then return end
            local delta = input.Position - dragStart
            if not dragMoved and (math.abs(delta.X) > DT or math.abs(delta.Y) > DT) then dragMoved = true end
            if dragMoved then
                f.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
            end
        end
        b.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = true; dragMoved = false; canDrag = false
                dragStart = input.Position; startPos = f.Position
                if holdThread then task.cancel(holdThread) holdThread = nil end
                holdThread = task.delay(HT, function() if dragging then canDrag = true end end)
            end
        end)
        b.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                if holdThread then task.cancel(holdThread) holdThread = nil end
                if dragging and not dragMoved then ToggleInvisStatus() end
                dragging = false; dragMoved = false; canDrag = false
                dragStart = nil; startPos = nil
            end
        end)
        UserInputService.InputChanged:Connect(function(input)
            if dragging and canDrag and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                update(input)
            end
        end)
    end
    task.spawn(function() task.wait(1.5); CreateCustomInvisGUI() end)

    -- ============ THE RAWKILLER/TOF SILENT AIM ============
    do
        local function getToFEvent()
            local r = ReplicatedStorage:FindFirstChild("Remotes")
            local i = r and r:FindFirstChild("Items")
            local t = i and i:FindFirstChild("Twist of Fate")
            return t and t:FindFirstChild("Fire")
        end
        local silentAimToFV1 = false
        local silentAimToFV2 = false
        local silentAimPredict = false
        local function IsToFSilentOn() return silentAimToFV1 or silentAimToFV2 end
        local laserEnabled = true
        local wallcheckEnabled = false
        local isAiming = false
        local Connection = nil
        local LaserBeam = nil
        local silentAimGui = nil
        local targetMode = "Killer"
        local savedUIPos = UDim2.new(0.5, -120, 0, 110)
        local velocityCache = {}
        local PREDICT_SETTINGS = { PredictionEfficiency = 0.85, LerpSmoothness = 0.4, EnableJitter = false, MaxJitterStuds = 0 }

        function getGunObject()
            local char = LocalPlayer.Character; if not char then return nil end
            local base = char:FindFirstChild("Twist of Fate", true); if not base then return nil end
            local ra = base:FindFirstChild("Right Arm")
            if ra then
                local g = ra:FindFirstChild("gun"); if g then return g end
                local eg = ra:FindFirstChild("EmperorGun"); if eg then return eg end
            end
            return base
        end
        function isTargetVisible(o, t, tc)
            local d = t - o; local dist = d.Magnitude
            if dist < 0.1 then return true end
            local rp = RaycastParams.new()
            rp.FilterType = Enum.RaycastFilterType.Exclude
            local ex = {}
            local lc = LocalPlayer.Character
            if lc then table.insert(ex, lc) end
            if tc and tc ~= lc then table.insert(ex, tc) end
            if LaserBeam then table.insert(ex, LaserBeam) end
            rp.FilterDescendantsInstances = ex
            return workspace:Raycast(o, d.Unit * dist, rp) == nil
        end
        local SCPCache = {}; local SCPCacheTimer = 0
        function GetSCPs()
            if tick() - SCPCacheTimer < 0.5 then return SCPCache end
            local nt = {}
            local mf = workspace:FindFirstChild("Map")
            if mf then
                for _, c in pairs(mf:GetDescendants()) do
                    if c:IsA("Model") then
                        local attr = c:GetAttributes()
                        if c:GetAttribute("CorpseCreated0492") or next(attr) ~= nil then
                            local r = c:FindFirstChild("HumanoidRootPart")
                            if r then table.insert(nt, r) end
                        end
                    end
                end
            end
            SCPCache = nt; SCPCacheTimer = tick()
            return SCPCache
        end
        local function getTargetVelocity(tc)
            local rp = tc:FindFirstChild("HumanoidRootPart"); if not rp then return Vector3.zero end
            local cp = rp.Position
            local ca = velocityCache[tc]
            if ca then
                local td = tick() - ca.time
                if td > 0.001 and td < 0.1 then
                    local rv = (cp - ca.pos) / td
                    local sv = ca.vel:Lerp(rv, PREDICT_SETTINGS.LerpSmoothness)
                    velocityCache[tc] = { pos = cp, vel = sv, time = tick() }
                    return sv
                end
            end
            velocityCache[tc] = { pos = cp, vel = rp.Velocity, time = tick() }
            return rp.Velocity
        end
        local function GetPredictedToFPosition(op, tp, tc, bs)
            bs = bs or 500
            local tpos = tp.Position
            local d = (tpos - op).Magnitude
            if d < 8 then return tpos end
            local tv = getTargetVelocity(tc)
            local rp = tpos - op
            local a = tv:Dot(tv) - (bs*bs)
            local b = 2 * rp:Dot(tv)
            local c = rp:Dot(rp)
            local t = nil
            if math.abs(a) < 0.01 then
                if math.abs(b) > 0.01 then t = -c/b end
            else
                local disc = b*b - 4*a*c
                if disc >= 0 then
                    local sq = math.sqrt(disc)
                    local t1 = (-b - sq) / (2*a)
                    local t2 = (-b + sq) / (2*a)
                    if t1 > 0.001 then t = t1 elseif t2 > 0.001 then t = t2 end
                end
            end
            local fp = tpos
            if t then
                local nv = tv * PREDICT_SETTINGS.PredictionEfficiency
                fp = tpos + (nv * t)
                if PREDICT_SETTINGS.EnableJitter then
                    fp = fp + Vector3.new((math.random()-0.5)*PREDICT_SETTINGS.MaxJitterStuds, (math.random()-0.5)*(PREDICT_SETTINGS.MaxJitterStuds/2), (math.random()-0.5)*PREDICT_SETTINGS.MaxJitterStuds)
                end
            end
            return fp
        end
        function getTargetPosition()
            local cam = workspace.CurrentCamera
            local gun = getGunObject()
            local char = LocalPlayer.Character
            if not (gun and char) then return nil, nil, nil, nil end
            local hrp = char:FindFirstChild("HumanoidRootPart"); if not hrp then return nil, nil, nil, nil end
            local myPos = hrp.Position
            local op
            if char:GetAttribute("IsCarried") then op = char.HumanoidRootPart.Position + (char.HumanoidRootPart.CFrame.LookVector * 2)
            else
                pcall(function()
                    op = gun:IsA("BasePart") and gun.Position or (gun:FindFirstChildOfClass("BasePart") and gun:FindFirstChildOfClass("BasePart").Position)
                end)
                op = op or Vector3.new(myPos.X, myPos.Y + 1.5, myPos.Z)
            end
            local function predictTarget(tp, tc)
                local tpos = tp.Position
                if wallcheckEnabled and not isTargetVisible(op, tpos, tc) then return nil, nil, nil, nil end
                local g = getGunObject()
                local co = op
                pcall(function()
                    if g and g:IsA("BasePart") then co = g.Position
                    elseif g then local p = g:FindFirstChildOfClass("BasePart"); if p then co = p.Position end end
                end)
                local d = (tpos - co).Magnitude
                if d < 8 then return (tpos - co).Unit, g, co, tpos end
                if not silentAimPredict then return (tpos - co).Unit, g, co, tpos end
                local pp = GetPredictedToFPosition(co, tp, tc, 500)
                return (pp - co).Unit, g, co, pp
            end
            if targetMode == "Killer" then
                local ct, cc, sd = nil, nil, math.huge
                for _, p in ipairs(_GetPlayers()) do
                    if p ~= LocalPlayer then
                        local ik = p.Team and p.Team.Name == "Killer"
                        if ik and p.Character then
                            local t = p.Character:FindFirstChild("Torso")
                            if t then
                                local d = (myPos - t.Position).Magnitude
                                if d < sd then sd = d; ct = t; cc = p.Character end
                            end
                        end
                    end
                end
                if not ct then return nil, nil, nil, nil end
                return predictTarget(ct, cc)
            elseif targetMode == "Survivors" then
                local bt, bc, bd = nil, nil, -math.huge
                local cam = workspace.CurrentCamera
                local cl = cam.CFrame.LookVector
                for _, p in ipairs(_GetPlayers()) do
                    if p ~= LocalPlayer and p.Team and p.Team.Name == "Survivors" and p.Character then
                        local t = p.Character:FindFirstChild("Torso")
                        if t then
                            local dt = (t.Position - cam.CFrame.Position).Unit
                            local dd = cl:Dot(dt)
                            if dd > 0.5 and dd > bd then bd = dd; bt = t; bc = p.Character end
                        end
                    end
                end
                if not bt then return nil, nil, nil, nil end
                return predictTarget(bt, bc)
            elseif targetMode == "Zombie" then
                local ts = GetSCPs()
                local bp, bd = nil, -math.huge
                local cam = workspace.CurrentCamera
                local cl = cam.CFrame.LookVector
                for _, r in ipairs(ts) do
                    if r and r.Parent then
                        local dt = (r.Position - cam.CFrame.Position).Unit
                        local dd = cl:Dot(dt)
                        if dd > 0.5 and dd > bd then bd = dd; bp = r end
                    end
                end
                if not bp then return nil, nil, nil, nil end
                return predictTarget(bp, bp.Parent)
            end
            return nil, nil, nil, nil
        end
        function updateLaser(op, tp)
            if not LaserBeam or not LaserBeam.Parent then
                if LaserBeam then pcall(function() LaserBeam:Destroy() end) end
                LaserBeam = Instance.new("Part")
                LaserBeam.Name = "ToFLaser"; LaserBeam.Anchored = true
                LaserBeam.CanCollide = false; LaserBeam.CanTouch = false
                LaserBeam.CastShadow = false; LaserBeam.Material = Enum.Material.Neon
                LaserBeam.Color = Color3.fromRGB(255,50,50); LaserBeam.Parent = workspace
            end
            local d = (tp - op).Magnitude
            if d < 0.1 then d = 0.1 end
            LaserBeam.Size = Vector3.new(0.05, 0.05, d)
            LaserBeam.CFrame = CFrame.new((op + tp) / 2, tp)
            LaserBeam.Transparency = 0
        end
        function clearLaser()
            if LaserBeam then LaserBeam:Destroy(); LaserBeam = nil end
        end
        function doShoot()
            if not IsToFSilentOn() then return end
            if silentAimToFV1 and not silentAimToFV2 then
                if not isAiming then return end
            end
            local char = LocalPlayer.Character
            if char and AimConfig.Pistol_BlockKnocked and IsDowned(char) then return end
            local td, go, op, tp = getTargetPosition()
            if not (td and go and tp and op) then return end
            local Te = getToFEvent(); if not Te then return end
            local fd = (tp - op).Unit
            pcall(function() Te:FireServer(go, fd) end)
        end
        function startConnection()
            if Connection then return end
            Connection = RunService.RenderStepped:Connect(function()
                if laserEnabled and IsToFSilentOn() and isAiming then
                    local char = LocalPlayer.Character
                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                    local op = nil
                    if hrp then
                        local hand = char:FindFirstChild("RightHand") or char:FindFirstChild("Right Arm")
                        op = (hand and hand:IsA("BasePart") and hand.Position) or (hrp.Position + Vector3.new(0, 1.5, 0))
                    end
                    if op then
                        local _, _, _, tp = getTargetPosition()
                        if tp then
                            updateLaser(op, tp)
                        else
                            if LaserBeam and LaserBeam.Parent then LaserBeam.Transparency = 1 end
                        end
                    end
                else
                    if LaserBeam and LaserBeam.Parent then LaserBeam.Transparency = 1 end
                end

                if isAiming and IsToFSilentOn() then
                    local td, go, op, tp = getTargetPosition()
                    if td and go and tp then
                        pcall(function()
                            local char = LocalPlayer.Character
                            local hrp = char and char:FindFirstChild("HumanoidRootPart")
                            if hrp and not char:GetAttribute("IsCarried") then
                                hrp.CFrame = CFrame.new(hrp.Position, Vector3.new(tp.X, hrp.Position.Y, tp.Z))
                            end
                        end)
                        if AimConfig.LockAim then
                            local tc = CFrame.lookAt(Camera.CFrame.Position, tp)
                            Camera.CFrame = Camera.CFrame:Lerp(tc, 0.15)
                        end
                    end
                end
            end)
        end
        function stopConnection()
            if Connection then Connection:Disconnect(); Connection = nil end
            clearLaser()
        end
        local targetGuiRef = nil
        local targetKeyConn = nil
        local MODES = {
            { internal = "Killer",    display = "Killer (K)",    activeColor = Color3.fromRGB(180,45,45), activeTxt = Color3.fromRGB(255,180,180) },
            { internal = "Survivors", display = "Survivors (J)", activeColor = Color3.fromRGB(25,80,150),  activeTxt = Color3.fromRGB(160,210,255) },
            { internal = "Zombie",    display = "Zombie (L)",    activeColor = Color3.fromRGB(120,80,10),  activeTxt = Color3.fromRGB(255,210,100) },
        }
        function createTargetSelectorUI()
            local cg = CoreGui; if not cg then return end
            if targetGuiRef and targetGuiRef.Parent then return end
            local old = cg:FindFirstChild("ToFTargetSelector"); if old then old:Destroy() end
            local gui = Instance.new("ScreenGui")
gui.Name = "ToFTargetSelector"; gui.ResetOnSpawn = false
gui.IgnoreGuiInset = true; gui.Parent = cg
local f = Instance.new("Frame")
f.Name = "Main"; f.Size = UDim2.new(0, 165, 0, 130)
f.Position = savedUIPos or UDim2.new(0.5, -82, 0.5, -65)
f.BackgroundColor3 = Color3.fromRGB(0, 0, 0); f.BorderSizePixel = 0
f.Active = true; f.Parent = gui
Instance.new("UICorner", f).CornerRadius = UDim.new(0, 10)
local s = Instance.new("UIStroke", f)
s.Color = Color3.fromRGB(255, 255, 255); s.Thickness = 0.8
local header = Instance.new("Frame")
header.Size = UDim2.new(1,0,0,24); header.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
header.BorderSizePixel = 0; header.Parent = f
Instance.new("UICorner", header).CornerRadius = UDim.new(0, 10)
local hFix = Instance.new("Frame")
hFix.Size = UDim2.new(1,0,0,10); hFix.Position = UDim2.new(0,0,1,-10)
hFix.BackgroundColor3 = Color3.fromRGB(0, 0, 0); hFix.BorderSizePixel = 0; hFix.Parent = header
local hDiv = Instance.new("Frame")
