local headerLbl = Instance.new("TextLabel")
headerLbl.Size = UDim2.new(1,-30,1,0); headerLbl.Position = UDim2.new(0,10,0,0)
headerLbl.BackgroundTransparency = 1
headerLbl.Text = "Target: Killer v"; headerLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
            headerLbl.Font = Enum.Font.GothamBold; headerLbl.TextSize = 9; headerLbl.Parent = header
            local bc = Instance.new("Frame")
            bc.Size = UDim2.new(1,-16,0,92); bc.Position = UDim2.new(0,8,0,30)
            bc.BackgroundTransparency = 1; bc.Parent = f
            local layout = Instance.new("UIListLayout", bc)
            layout.SortOrder = Enum.SortOrder.LayoutOrder; layout.Padding = UDim.new(0,6)
            local btnRefs = {}
