            local function updateButtons()
                for _, m in ipairs(MODES) do
                    local b = btnRefs[m.internal]
                    if b then
                        if m.internal == targetMode then
                            b.BackgroundColor3 = m.activeColor; b.TextColor3 = m.activeTxt
                            if headerLbl then headerLbl.Text = "Target: " .. m.display .. " v" end
