            minBtn.MouseButton1Click:Connect(toggleMin)
            for _, c in ipairs(bc:GetChildren()) do if c:IsA("TextButton") then c:Destroy() end end
            for i, m in ipairs(MODES) do
                local b = Instance.new("TextButton")
                b.Size = UDim2.new(1,0,0,26); b.BorderSizePixel = 0
                b.Font = Enum.Font.GothamBold; b.TextSize = 11; b.Text = m.display
                b.LayoutOrder = i; b.Parent = bc
                Instance.new("UICorner", b).CornerRadius = UDim.new(0, 6)
                b.MouseButton1Click:Connect(function() targetMode = m.internal; updateButtons() end)
                b.InputEnded:Connect(function(inp) if inp.UserInputType == Enum.UserInputType.Touch then targetMode = m.internal; updateButtons() end end)
                btnRefs[m.internal] = b
            end
            updateButtons()
            local drag = false
            local ds, sp
            dragArea.InputBegan:Connect(function(inp)
                if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
                    ds = inp.Position; sp = f.Position; drag = true
                end
            end)
            dragArea.InputEnded:Connect(function(inp)
                if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then drag = false end
            end)
            UserInputService.InputChanged:Connect(function(inp)
                if not drag then return end
                if inp.UserInputType == Enum.UserInputType.MouseMovement or inp.UserInputType == Enum.UserInputType.Touch then
                    local d = inp.Position - ds
                    local np = UDim2.new(sp.X.Scale, sp.X.Offset + d.X, sp.Y.Scale, sp.Y.Offset + d.Y)
                    f.Position = np; savedUIPos = np
                end
            end)
            if targetKeyConn then targetKeyConn:Disconnect(); targetKeyConn = nil end
            targetKeyConn = UserInputService.InputBegan:Connect(function(inp, gp)
                if not IsToFSilentOn() then return end
                if gp or inp.UserInputType ~= Enum.UserInputType.Keyboard then return end
                local nm = nil
                if inp.KeyCode == Enum.KeyCode.K then nm = "Killer"
                elseif inp.KeyCode == Enum.KeyCode.J then nm = "Survivors"
                elseif inp.KeyCode == Enum.KeyCode.L then nm = "Zombie" end
                if nm and nm ~= targetMode then
                    targetMode = nm
                    for mn, b in pairs(btnRefs) do
                        if b and b.Parent then
                            local ia = (mn == targetMode)
                            for _, m in ipairs(MODES) do
                                if m.internal == mn then
                                    b.BackgroundColor3 = ia and m.activeColor or Color3.fromRGB(38,38,38)
                                    b.TextColor3 = ia and m.activeTxt or Color3.fromRGB(130,130,130)
                                    if ia and headerLbl then headerLbl.Text = "Target: " .. m.display .. " v" end
                                end
                            end
                        end
                    end
                end
            end)
            targetGuiRef = gui
