    function getKillerTargetForFlash()
        local best = nil; local cd = math.huge
        local myC = LocalPlayer.Character
        local mh = myC and myC:FindFirstChild("HumanoidRootPart"); if not mh then return nil end
        for _, p in ipairs(_GetPlayers()) do
            if p ~= LocalPlayer and IsKiller(p) and p.Character then
                local h = p.Character:FindFirstChildOfClass("Humanoid")
                local hh = p.Character:FindFirstChild("HumanoidRootPart")
                if h and h.Health > 0 and hh and not IsDowned(p.Character) then
                    local d = (hh.Position - mh.Position).Magnitude
                    if d < cd then cd = d; best = hh end
                end
            end
        end
        return best
    end

