    function DBD_StartLoop()
    if DBD_Conn then return end
    DBD_Conn = "DBD_Cam_BINTANG"

    RunService:BindToRenderStep(DBD_Conn, Enum.RenderPriority.Camera.Value + 1, function()
        if not DBD_Config.Enabled then return end
        local cam = workspace.CurrentCamera
        if not cam then return end

        if cam.FieldOfView ~= DBD_Config.FOV then
            cam.FieldOfView = DBD_Config.FOV
        end

        local d = DBD_Config.Distance
        local minZ = math.max(0.1, d - 0.5)
        local maxZ = d + 0.5
        if LocalPlayer.CameraMinZoomDistance ~= minZ then
            LocalPlayer.CameraMinZoomDistance = minZ
        end
        if LocalPlayer.CameraMaxZoomDistance ~= maxZ then
            LocalPlayer.CameraMaxZoomDistance = maxZ
        end

        local char = LocalPlayer.Character
        if char then
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum and hum.CameraOffset.Y ~= DBD_Config.Height then
                hum.CameraOffset = Vector3.new(0, DBD_Config.Height, 0)
            end
        end
    end)
end

