                if getgenv().NEX_CureFlaskLaserThread then
                    getgenv().NEX_CureFlaskLaserThread:Disconnect()
                    getgenv().NEX_CureFlaskLaserThread = nil
                end
                return
            end
            pcall(NEX_UpdateCureFlaskLaser)
        end)
    end

    -- ============ ANTI LOOPING ============
    _G.BlockPalletEnabled = false

    function StartAntiLooping()
        local Remotes = game:GetService("ReplicatedStorage").Remotes
        local VaultEvent = Remotes.Window.VaultEvent
        local PalletEvent = Remotes.Pallet.PalletSlideEvent
        local map = workspace:FindFirstChild("Map")
        if map then
            for _, trig in pairs(map:GetDescendants()) do
                if trig.Name == "VaultTrigger" then
                    pcall(function() VaultEvent:FireServer(trig, true) end)
                end
                if trig.Name == "PalletPointSlide" and trig:IsA("BasePart") then
                    pcall(function() PalletEvent:FireServer(trig, true) end)
                end
            end
        end
        task.spawn(function()
            local m = workspace:FindFirstChild("Map")
            if not m then return end
            local conns = {}
            local function watchPallet(obj)
                if obj:IsA("BasePart") and obj.Name == "PalletPoint" then
                    table.insert(conns, obj:GetPropertyChangedSignal("Name"):Connect(function()
                        if not _G.BlockPalletEnabled then return end
                        if obj.Name == "PalletPointSlide" then
                            task.wait(0.1)
                            pcall(function() PalletEvent:FireServer(obj, true) end)
                        end
                    end))
                end
            end
            for _, obj in pairs(m:GetDescendants()) do watchPallet(obj) end
            table.insert(conns, m.DescendantAdded:Connect(function(obj) watchPallet(obj) end))
            while _G.BlockPalletEnabled do task.wait(0.5) end
            for _, c in pairs(conns) do c:Disconnect() end
        end)
    end

    function StopAntiLooping()
        local R = game:GetService("ReplicatedStorage").Remotes
        local VCE = R.Window.VaultCompleteEvent
        local PCE = R.Pallet.PalletSlideCompleteEvent
        local map = workspace:FindFirstChild("Map")
        if map then
            for _, obj in pairs(map:GetDescendants()) do
                if obj.Name == "VaultPointInUse" then
                    pcall(function() VCE:FireServer(obj.Parent, false) end)
                elseif obj.Name == "PalletPointSlideInUse" then
                    pcall(function() PCE:FireServer(obj.Parent, false) end)
                end
            end
        end
    end

    -- ============ THIRD PERSON HELPERS ============
    armParts = armParts or {
        ["Left Arm"]=true, ["Right Arm"]=true,
        ["LeftHand"]=true, ["RightHand"]=true,
        ["LeftLowerArm"]=true, ["RightLowerArm"]=true,
        ["LeftUpperArm"]=true, ["RightUpperArm"]=true
    }

    function isWeapon(obj)
        if not obj or not obj:IsA("BasePart") then return false end
        local n = obj.Name:lower()
        return n:find("knife") or n:find("sword") or n:find("weapon")
            or n:find("axe") or n:find("bat") or n:find("gun")
            or n:find("spear") or n:find("flask") or n:find("stick")
    end

    function ResetAllTransparency()
        for _, obj in pairs(Camera:GetChildren()) do
            if obj ~= LocalPlayer.Character then
                for _, p in pairs(obj:GetDescendants()) do
                    if p:IsA("BasePart") or p:IsA("Decal") then
                        pcall(function()
                            p.LocalTransparencyModifier = 0
                            p.Transparency = 0
                        end)
                    end
                end
            end
        end
    end

    function SetWorldTransparency(t)
        for _, obj in pairs(Camera:GetChildren()) do
            if obj ~= LocalPlayer.Character then
                for _, p in pairs(obj:GetDescendants()) do
                    if p:IsA("BasePart") or p:IsA("Decal") then
                        pcall(function()
                            p.LocalTransparencyModifier = t
                            p.Transparency = t
                        end)
                    end
                end
            end
        end
    end

    function SetCharacterTransparency(c, t)
        if not c then return end
        for _, obj in pairs(c:GetChildren()) do
            if obj.Name == "Hat" then
                for _, ch in pairs(obj:GetDescendants()) do
                    if ch:IsA("BasePart") or ch:IsA("Decal") then
                        pcall(function()
                            ch.LocalTransparencyModifier = t
                            ch.Transparency = t
                        end)
                    end
                end
            end
            if obj:IsA("BasePart") and armParts and armParts[obj.Name] then
                pcall(function()
                    obj.LocalTransparencyModifier = t
                    obj.Transparency = t
                end)
            end
            if isWeapon(obj) then
                local d = obj:IsA("BasePart") and {obj} or obj:GetDescendants()
                for _, ch in pairs(d) do
                    if ch:IsA("BasePart") or ch:IsA("Decal") then
                        pcall(function()
                            ch.LocalTransparencyModifier = t
                            ch.Transparency = t
                        end)
                    end
                end
            end
        end
    end

    function ResetCharacterTransparency(isKiller)
        if not LocalPlayer.Character then return end
        if isKiller then
            for _, obj in pairs(LocalPlayer.Character:GetChildren()) do
                if obj.Name == "Hat" then
                    for _, ch in pairs(obj:GetDescendants()) do
                        if ch:IsA("BasePart") or ch:IsA("Decal") then
                            pcall(function()
                                ch.LocalTransparencyModifier = 1
                                ch.Transparency = 1
                            end)
                        end
                    end
                end
                if obj:IsA("BasePart") and armParts and armParts[obj.Name] then
                    pcall(function()
                        obj.LocalTransparencyModifier = 1
                        obj.Transparency = 1
                    end)
                end
                if isWeapon(obj) then
                    local d = obj:IsA("BasePart") and {obj} or obj:GetDescendants()
                    for _, ch in pairs(d) do
                        if ch:IsA("BasePart") or ch:IsA("Decal") then
                            pcall(function()
                                ch.LocalTransparencyModifier = 1
                                ch.Transparency = 1
                            end)
                        end
                    end
                end
            end
        else
            SetCharacterTransparency(LocalPlayer.Character, 0)
        end
    end

    -- ============ ANTI AUTO PARRY - LOOP ============
    task.spawn(function()
        while true do
            task.wait(0.7)
            if not AntiAutoParryEnabled then continue end
            local char = LocalPlayer.Character
            if not char then continue end
            local myRoot = char:FindFirstChild("HumanoidRootPart")
            if not myRoot then continue end
            local near = false
            for _, p in ipairs(_GetPlayers()) do
                if p ~= LocalPlayer and p.Team and p.Team.Name == "Survivors" then
                    local r = p.Character and p.Character:FindFirstChild("HumanoidRootPart")
                    if r and (myRoot.Position - r.Position).Magnitude <= 15 then
                        near = true
                        break
                    end
                end
            end
            if near then
                local randomId = ParryAnimList[math.random(1, #ParryAnimList)]
                local anim = Instance.new("Animation")
                anim.AnimationId = "rbxassetid://" .. randomId
                local hum = char:FindFirstChildOfClass("Humanoid")
                local animator = hum and hum:FindFirstChildOfClass("Animator")
                if animator then
                    local track = animator:LoadAnimation(anim)
                    track:Play()
                    track:AdjustWeight(0)
                    task.wait(0.05)
                    track:Stop()
                    anim:Destroy()
                end
            end
        end
    end)

