        WatermarkLabel.Text = "BINTANG"
        WatermarkLabel.Parent = frame

        local dragging, dragStart, startPos = false, nil, nil
        frame.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = true
                dragStart = input.Position
                startPos = frame.Position
            end
        end)
        frame.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = false
            end
        end)
        UserInputService.InputChanged:Connect(function(input)
            if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                local delta = input.Position - dragStart
                frame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
            end
        end)
    end

    function StartWatermark()
        if WatermarkConnection then WatermarkConnection:Disconnect(); WatermarkConnection = nil end
        CreateWatermarkGui()
        if not WatermarkGui then return end
        local frame = WatermarkGui:FindFirstChild("Frame")
        if frame then frame.Visible = true end

        local FrameTimer = tick()
        local FrameCounter = 0
        local FPS = 60
        WatermarkConnection = RunService.Heartbeat:Connect(function()
            if not WatermarkEnabled then
                if WatermarkConnection then WatermarkConnection:Disconnect(); WatermarkConnection = nil end
                if WatermarkGui then
                    local f = WatermarkGui:FindFirstChild("Frame")
                    if f then f.Visible = false end
                end
                return
            end
            FrameCounter = FrameCounter + 1
            if (tick() - FrameTimer) >= 1 then
                FPS = FrameCounter
                FrameTimer = tick()
                FrameCounter = 0
            end
            local ping = 0
            pcall(function()
                ping = math.floor(game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue() or 0)
            end)
            if WatermarkLabel then
                WatermarkLabel.Text = ("BINTANG | %s fps | %s ms"):format(math.floor(FPS), ping)
            end
        end)
    end

    function StopWatermark()
        WatermarkEnabled = false
        if WatermarkConnection then WatermarkConnection:Disconnect(); WatermarkConnection = nil end
        if WatermarkGui then
            local f = WatermarkGui:FindFirstChild("Frame")
            if f then f.Visible = false end
        end
    end

