    task.spawn(function()
        while true do
            task.wait(0.15)
            if UserInputService.TouchEnabled then continue end
            if tick() - lastActionTime < COOLDOWN then continue end
            local wantV = autoVaultEnabled
            local wantS = autoPalletSlideEnabled
            if not wantV and not wantS then continue end
            local pc = PlayerGui:FindFirstChild("pcprompts")
            local fr = pc and pc:FindFirstChild("Frame")
            if not fr then continue end
            local vg = fr:FindFirstChild("VaultPromptGui")
            local sg = fr:FindFirstChild("PalletSlidePromptGui")
            local vV = vg and vg.Visible
            local sV = sg and sg.Visible
            if (wantV and vV) or (wantS and sV) then
                VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.Space, false, game)
                task.wait(0.01)
                VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.Space, false, game)
                lastActionTime = tick()
            end
        end
    end)
    local function setupMobileVault()
        if not UserInputService.TouchEnabled then return end
        local mg = PlayerGui:FindFirstChild("Survivor-mob") or PlayerGui:WaitForChild("Survivor-mob", 8)
        if not mg then return end
        local cc = mg:FindFirstChild("Controls") or mg:WaitForChild("Controls", 5)
        local a = cc and (cc:FindFirstChild("action") or cc:WaitForChild("action", 5))
        if not a then return end
        local allowed = { vault = true, palletvault = true, palletslide = true, slide = true }
        local function connectLabel(child)
            if not (child:IsA("ImageLabel") or child:IsA("ImageButton")) then return end
            local n = child.Name:lower()
            if not allowed[n] then return end
            child:GetPropertyChangedSignal("Visible"):Connect(function()
                if not child.Visible then return end
                if tick() - lastActionTime < COOLDOWN then return end
                local isV = n:find("vault") and not n:find("pallet")
                local isS = n:find("pallet") or n:find("slide")
                if (isV and autoVaultEnabled) or (isS and autoPalletSlideEnabled) then
                    pcall(function()
                        firesignal(a.MouseButton1Down)
                        task.wait(0.01)
                        firesignal(a.MouseButton1Up)
                    end)
                    lastActionTime = tick()
                end
            end)
        end
        for _, c in pairs(a:GetChildren()) do connectLabel(c) end
        a.ChildAdded:Connect(function(c) task.wait(); connectLabel(c) end)
    end
    task.spawn(setupMobileVault)
    LocalPlayer.CharacterAdded:Connect(function() task.wait(2); setupMobileVault() end)
    PlayerGui.ChildAdded:Connect(function(c) if c.Name == "Survivor-mob" then task.wait(1); setupMobileVault() end end)

