    local function CreateSimpleButton()
        if Button.Gui then pcall(function() Button.Gui:Destroy() end) end
        local parent = LocalPlayer:FindFirstChild("PlayerGui")
        if gethui then local ok, hui = pcall(gethui); if ok and hui then parent = hui end end
        if not parent then return end

        local gui = Instance.new("ScreenGui")
        gui.Name = "GlutoUnhookBtn"
        gui.ResetOnSpawn = false
        gui.IgnoreGuiInset = true
        gui.Parent = parent
        Button.Gui = gui

        local btn = Instance.new("TextButton")
        btn.Name = "Btn"
        btn.Size = UDim2.fromOffset(110, 42)
        btn.Position = UDim2.new(0.85, -55, 0.5, -21)
        btn.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
        btn.BorderSizePixel = 0
        btn.Text = "Unhook"
        btn.TextColor3 = Color3.fromRGB(120, 120, 120)
        btn.TextSize = 14
        btn.Font = Enum.Font.GothamBold
        btn.AutoButtonColor = false
        btn.Parent = gui
        Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 10)
        Button.Btn = btn

        UpdateButtonVisual()

        local drag = false
        local dStart, sPos
        local dDist = 0

        btn.InputBegan:Connect(function(inp)
            if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
                dStart = inp.Position; sPos = btn.Position; dDist = 0
                drag = true
            end
        end)

        btn.InputEnded:Connect(function(inp)
            if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
                if drag and dDist < 8 then
                    local newState = not W.SelfUnhook.Enabled
                    W.SU_SetEnabled(newState)
                end
                drag = false
            end
        end)

        UserInputService.InputChanged:Connect(function(inp)
            if not drag then return end
            if inp.UserInputType == Enum.UserInputType.MouseMovement or inp.UserInputType == Enum.UserInputType.Touch then
                local d = inp.Position - dStart
                dDist = math.abs(d.X) + math.abs(d.Y)
                btn.Position = UDim2.new(sPos.X.Scale, sPos.X.Offset + d.X, sPos.Y.Scale, sPos.Y.Offset + d.Y)
            end
        end)
    end

    local function DestroySimpleButton()
        if Button.Gui then pcall(function() Button.Gui:Destroy() end); Button.Gui = nil; Button.Btn = nil end
    end

