    -- Auto Pallet Section
    local PalletGroup = SurvivorTab:CreateSection({ Name = "Auto Pallet", Side = "Left" })
    PalletGroup:AddButton({ Name = "Drop All Pallet", Callback = function()
        local r = ReplicatedStorage:FindFirstChild("Remotes")
        local de = r and r:FindFirstChild("Pallet") and r.Pallet:FindFirstChild("PalletDropEvent")
        local pg = {}
        local function refresh()
            pg = {}
            local m = workspace:FindFirstChild("Map"); if not m then return end
            for _, d in ipairs(m:GetDescendants()) do
                if d.Name == "PalletPoint" and d:IsA("BasePart") then
                    local pm = d:FindFirstAncestorWhichIsA("Model")
                    if pm then
                        if not pg[pm] then pg[pm] = {} end
                        table.insert(pg[pm], d)
                    end
                end
            end
        end
        refresh()
        for _, pts in pairs(pg) do
            for _, p in ipairs(pts) do
                pcall(function() de:FireServer(p) end)
            end
        end
    end })
