    -- SECTION: CAMERA SETTING — RIGHT
    local KillerCamGroup = KillerTab:CreateSection({ Name = "Camera Setting", Side = "Right" })

    UI.KillerThirdPerson = KillerCamGroup:AddToggle({
        Name = "Third Person (Killer)", Default = false, ConfigKey = "killer_3rdperson",
        Callback = function(Value)
            local isKillerRole = (player.Team and player.Team.Name == "Killer")
            if Value and not isKillerRole then
                if UI.KillerThirdPerson then UI.KillerThirdPerson.Set(false) end
                return
            end
            Config.Killer_3rdPerson = Value
            if not Value then
                if State.ThirdPersonConn then
                    State.ThirdPersonConn:Disconnect()
                    State.ThirdPersonConn = nil
                end
                if isKillerRole then
                    player.CameraMode = Enum.CameraMode.LockFirstPerson
                    player.CameraMinZoomDistance = 0.5
                    player.CameraMaxZoomDistance = 0.5
                else
                    player.CameraMode = Enum.CameraMode.Classic
                    player.CameraMinZoomDistance = 0.5
                    player.CameraMaxZoomDistance = 128
                end
                ResetAllTransparency()
                if player.Character then ResetCharacterTransparency(false) end
            else
                player.CameraMode = Enum.CameraMode.Classic
                player.CameraMinZoomDistance = 7
                player.CameraMaxZoomDistance = 128
                if State.ThirdPersonConn then
                    State.ThirdPersonConn:Disconnect()
                    State.ThirdPersonConn = nil
                end
                State.ThirdPersonConn = RunService.RenderStepped:Connect(function()
                    if _frameCounter % 2 ~= 0 then return end
                    if not Config.Killer_3rdPerson then return end
                    if player.Team and player.Team.Name ~= "Killer" then
                        Config.Killer_3rdPerson = false
                        if State.ThirdPersonConn then
                            State.ThirdPersonConn:Disconnect()
                            State.ThirdPersonConn = nil
                        end
                        return
                    end
                    player.CameraMode = Enum.CameraMode.Classic
                    player.CameraMinZoomDistance = 7
                    player.CameraMaxZoomDistance = 128
                    SetWorldTransparency(1)
                    if player.Character then
                        SetCharacterTransparency(player.Character, 0)
                    end
                end)
            end
        end
